@startuml

class Aircraft {
  + Model : string
  + Price : double
}

class Contract {
  + GlobalContractId : string
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + ContractId : string
  + AircraftModel : string
  + NegotiatedPrice : double
  + Options : string
  + Customizations : string
  + DeliveryDate : date
}

class Salesperson {
  + Name : string
}

class Airline {
  + Name : string
  + ParentAirline : Airline
}

Contract "1" -- "0..*" Acquisition
Salesperson "0..1" -- "0..*" Contract
Aircraft "0..1" -- "0..*" Acquisition
Airline "0..1" *-- "0..1" Airline

@enduml

